type ContextClient struct{ client *NativeClient }

func NewContextClient(o NativeOptions) (*ContextClient, error) {
	c, e := NewNativeClient("context", o)
	if e != nil {
		return nil, e
	}
	return &ContextClient{client: c}, nil
}
func (c *ContextClient) Operations() []Operation { return c.client.Operations() }
func (c *ContextClient) Call(ctx context.Context, name string, input NativeInput) (NativeResult, error) {
	return c.client.Call(ctx, name, input)
}
